module pc(clk, rst, next_pc, pc);
  input clk;
  wire clk;
  input [15:0] next_pc;
  wire [15:0] next_pc;
  output [15:0] pc;
  reg [15:0] pc = 16'h0000;
  input rst;
  wire rst;
  always @(posedge clk, posedge rst)
    if (rst) pc[0] <= 1'h0;
    else pc[0] <= next_pc[0];
  always @(posedge clk, posedge rst)
    if (rst) pc[1] <= 1'h0;
    else pc[1] <= next_pc[1];
  always @(posedge clk, posedge rst)
    if (rst) pc[2] <= 1'h0;
    else pc[2] <= next_pc[2];
  always @(posedge clk, posedge rst)
    if (rst) pc[3] <= 1'h0;
    else pc[3] <= next_pc[3];
  always @(posedge clk, posedge rst)
    if (rst) pc[4] <= 1'h0;
    else pc[4] <= next_pc[4];
  always @(posedge clk, posedge rst)
    if (rst) pc[5] <= 1'h0;
    else pc[5] <= next_pc[5];
  always @(posedge clk, posedge rst)
    if (rst) pc[6] <= 1'h0;
    else pc[6] <= next_pc[6];
  always @(posedge clk, posedge rst)
    if (rst) pc[7] <= 1'h0;
    else pc[7] <= next_pc[7];
  always @(posedge clk, posedge rst)
    if (rst) pc[8] <= 1'h0;
    else pc[8] <= next_pc[8];
  always @(posedge clk, posedge rst)
    if (rst) pc[9] <= 1'h0;
    else pc[9] <= next_pc[9];
  always @(posedge clk, posedge rst)
    if (rst) pc[10] <= 1'h0;
    else pc[10] <= next_pc[10];
  always @(posedge clk, posedge rst)
    if (rst) pc[11] <= 1'h0;
    else pc[11] <= next_pc[11];
  always @(posedge clk, posedge rst)
    if (rst) pc[12] <= 1'h0;
    else pc[12] <= next_pc[12];
  always @(posedge clk, posedge rst)
    if (rst) pc[13] <= 1'h0;
    else pc[13] <= next_pc[13];
  always @(posedge clk, posedge rst)
