module status_register(clk, rst, latch_en, opcode_in, z_in, n_in, c_in, v_in, last_opcode, z, n, c, v, flags_packed);
  output c;
  reg c;
  input c_in;
  wire c_in;
  input clk;
  wire clk;
  output [3:0] flags_packed;
  wire [3:0] flags_packed;
  output [6:0] last_opcode;
  reg [6:0] last_opcode;
  input latch_en;
  wire latch_en;
  output n;
  reg n;
  input n_in;
  wire n_in;
  input [6:0] opcode_in;
  wire [6:0] opcode_in;
  input rst;
  wire rst;
  output v;
  reg v;
  input v_in;
  wire v_in;
  output z;
  reg z;
  input z_in;
  wire z_in;
  always @(posedge clk, posedge rst)
    if (rst) z <= 1'h0;
    else if (latch_en) z <= z_in;
  always @(posedge clk, posedge rst)
    if (rst) n <= 1'h0;
    else if (latch_en) n <= n_in;
  always @(posedge clk, posedge rst)
    if (rst) c <= 1'h0;
    else if (latch_en) c <= c_in;
  always @(posedge clk, posedge rst)
    if (rst) v <= 1'h0;
    else if (latch_en) v <= v_in;
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[0] <= 1'h0;
    else if (latch_en) last_opcode[0] <= opcode_in[0];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[1] <= 1'h0;
    else if (latch_en) last_opcode[1] <= opcode_in[1];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[2] <= 1'h0;
    else if (latch_en) last_opcode[2] <= opcode_in[2];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[3] <= 1'h0;
    else if (latch_en) last_opcode[3] <= opcode_in[3];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[4] <= 1'h0;
    else if (latch_en) last_opcode[4] <= opcode_in[4];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[5] <= 1'h0;
    else if (latch_en) last_opcode[5] <= opcode_in[5];
  always @(posedge clk, posedge rst)
    if (rst) last_opcode[6] <= 1'h0;
    else if (latch_en) last_opcode[6] <= opcode_in[6];
  assign flags_packed = { z, n, c, v };
endmodule
